import{_ as r,l as s,o as e,c as i,v as o,p as n,x as l,d,i as c,S as D}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"AQM：RED 与 CoDel","description":"","frontmatter":{"title":"AQM：RED 与 CoDel","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aqm-red-codel.md","filePath":"cs/aqm-red-codel.md","lastUpdated":1789023840000}'),h={name:"cs/aqm-red-codel.md"};function p(E,a,C,A,m,_){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="aqm-red-与-codel" tabindex="-1">AQM：RED 与 CoDel <a class="header-anchor" href="#aqm-red-与-codel" aria-label="Permalink to &quot;AQM：RED 与 CoDel&quot;">​</a></h1><div class="epigraph"><p>尾丢把队列撑满才说话；主动队列管理提前丢或标记，给 AIMD 信号，并压住延迟。</p><footer>—— 据 Floyd and Jacobson, RED, IEEE/ACM ToN 1993；Nichols and Jacobson, CoDel, ACM Queue 2012；RFC 8289 整理</footer></div><p><a href="/cs/cc-fairness-rtt">RTT 不公平</a> 与 <a href="/cs/incast">incast</a> 都怪队列。<a href="/cs/cc-fairness-rtt">上一课</a> 留下调度器与 AQM 两条路。缺口是 <strong>RED/CoDel</strong>：按平均队列或驻留时间丢/标。本课不把 ECN 协商写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>尾丢 = 满了才丢，信号晚、同步多流一起 MD。RED：平均队列在 min/max 间概率丢。难调，平均队列不是延迟。CoDel：测包的驻留，超过 target 一段时间则丢，参数按时间不是按包数，适配带宽变化。PIE 同类。数据中心浅阈标记更近 DCTCP，公网盒常 CoDel/FQ-CoDel。</p><p>不要把 AQM 写成提高 \\(C\\)：它管的是延迟与信号时机。</p><p><span class="marginnote">RFC 7567 AQM 建议。RFC 8289 CoDel。本课不把 RED 权值当考试。</span></p><h3 id="早期信号换浅延迟" tabindex="-1">早期信号换浅延迟 <a class="header-anchor" href="#早期信号换浅延迟" aria-label="Permalink to &quot;早期信号换浅延迟&quot;">​</a></h3><p>不增加 \\(C\\)。RED 按深度难调；CoDel 按驻留。FQ-CoDel 顺带隔离流。极浅 cut-through 无队列可管。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：尾丢 / RED / CoDel。画：入队 → 测延迟 → 超阈则丢或 CE。与 PFC：一个丢/标，一个暂停，对象都是队列，哲学相反。</p>',11)),(e(),n(D,null,{default:l(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%98%9F%E5%88%97%22%5D%20--%3E%20TAIL%5B%22%E5%B0%BE%E4%B8%A2%3A%20%E6%BB%A1%E6%89%8D%E4%B8%A2%22%5D%0A%20%20Q%20--%3E%20RED%5B%22RED%3A%20%E5%B9%B3%E5%9D%87%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20CD%5B%22CoDel%3A%20%E9%A9%BB%E7%95%99%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FQ-CoDel 每流队列再 CoDel，顺带修 RTT 不公平与缓冲膨胀。交换机 ASIC 未必能每流，数据中心用简单阈。卫星：CoDel target 要大于固有 RTT 的排队部分，不能把传播时延当膨胀。P4 可实现自定义 AQM。</p><p>同步：随机早期丢减少全局同步，几何上仍 AIMD。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 L4S 双队列全文。ECN 是下一课。后课默认：AQM 用早期信号换浅延迟；参数以时间为宜。</p><p>在极浅缓冲的 cut-through 盒上 AQM 无队列可管。</p><p>上一课留下的缺口在本课收口；「AQM：RED 与 CoDel」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ecn">ECN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾丢信号晚且易同步。</li><li>RED 按深度，CoDel 按驻留。</li><li>不增加容量，改善延迟与反馈。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Floyd–Jacobson, 1993；Nichols–Jacobson；RFC 8289。</li></ul>',10))])}const R=r(h,[["render",p]]);export{f as __pageData,R as default};
